#!/usr/bin/env python3
"""Generate the 2048-point periodic-Hann and signed Q1.17 FFT coefficients."""
import argparse
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render():
    lines = [
        "`default_nettype none",
        "// Generated by ae350/scripts/generate_fft2048_rom.py; 2048 points, Fs=48k.",
        "module audio_analysis_rom(input wire clk,input wire [10:0] window_addr,",
        " input wire [9:0] twiddle_addr,output reg [15:0] window_gain,",
        " output reg signed [17:0] twiddle_re,twiddle_im);",
        "always @(posedge clk) begin",
        " case(window_addr)",
    ]
    for n in range(2048):
        hann = round((0.5 - 0.5 * math.cos(2 * math.pi * n / 2048)) * 65535)
        lines.append(f"  11'd{n}: window_gain <= 16'd{hann};")
    lines += [" endcase", " case(twiddle_addr)"]
    for n in range(1024):
        real = max(-131072, min(131071, round(math.cos(2 * math.pi * n / 2048) * 131072)))
        imag = max(-131072, min(131071, round(-math.sin(2 * math.pi * n / 2048) * 131072)))
        word = ((real & 0x3ffff) << 18) | (imag & 0x3ffff)
        lines.append(f"  10'd{n}: {{twiddle_re,twiddle_im}} <= 36'h{word:09x};")
    lines += [" endcase", "end", "endmodule", "`default_nettype wire", ""]
    return "\n".join(lines)


def render_columns():
    lines = ["// Generated bin-to-column map. Each measured peak belongs to one bar.",
        "module gw138k_spectrum_column_rom(input wire clk,input wire [9:0] bin,output reg [8:0] column);",
        "    always @(posedge clk) case(bin)"]
    for n in range(1024):
        col = round(511 * math.log(max(2, min(853, n))/2) / math.log(853/2))
        lines.append(f"        10'd{n}: column<=9'd{col};")
    lines += ["        default: column<=0;", "    endcase", "endmodule", "`default_nettype wire", ""]
    return "\n".join(lines)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = ROOT / "video/audio_analysis_rom.v"
    if args.check:
        assert path.read_text() == render(), "2048-point FFT coefficients are stale"
        analysis = (ROOT / "video/output_audio_analysis.v").read_text()
        assert analysis[analysis.index("// Generated bin-to-column map."):] == render_columns(), "Bar column map is stale"
        print("PASS 2048-point coefficients and logarithmic bar columns")
    else:
        path.write_text(render())
        analysis_path = ROOT / "video/output_audio_analysis.v"
        analysis = analysis_path.read_text()
        analysis_path.write_text(analysis[:analysis.index("// Generated bin-to-column map.")] + render_columns())
        print(path)
